package com.yuyutian.mytools.media.library.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.client.RestClient;import com.yuyutian.mytools.media.library.service.MediaTaskSchedulerClient;
/** Media Library 配置。 */ @Configuration public class MediaLibraryConfiguration { /** 创建事务模板。 @param manager 管理器 @return 模板 */ @Bean public TransactionTemplate transactions(PlatformTransactionManager manager){return new TransactionTemplate(manager);} /** 创建内部令牌。 @param value 值 @return 令牌 */ @Bean public InternalToken internalToken(@Value("${media-library.internal-token:}")String value){return new InternalToken(value);} /** 内部令牌。 */ public record InternalToken(String value){} /** 创建调度客户端。 @param builder 构建器 @param url 地址 @return 客户端 */ @Bean public MediaTaskSchedulerClient schedulerClient(RestClient.Builder builder,@Value("${media-library.task-scheduler-url:http://127.0.0.1:23100}")String url){return new MediaTaskSchedulerClient(builder.baseUrl(url).build());} }
